    # Precompute the number of valid sequences of length i
    dp = [0] * n
    dp[0] = 1
    for i in range(1, n):
        dp[i] = sum(dp[j] for j in range(i) if (j + 1) % n != 0) % MOD

    # Function to find the k-th sequence using backtracking
    def backtrack(length, current_sum, path):
        if length == n - 1:
            return path

        for petals in range(1, n):
            new_sum = (current_sum + petals) % n
            if new_sum != 0:
                k -= dp[length]
                if k <= 0:
                    return backtrack(length + 1, new_sum, path + [petals])

    return backtrack(0, 0, [])

