def find_kth_sequence(n, k):
    MOD = 10**9 + 7

    # Function to compute the number of valid sequences of length m
    def count_sequences(m):
        dp = [[0] * n for _ in range(m + 1)]
        dp[0][0] = 1

        for i in range(1, m + 1):
            for j in range(n):
                for p in range(1, n):
                    if (j + p) % n != 0:
                        dp[i][(j + p) % n] += dp[i - 1][j]
                        dp[i][(j + p) % n] %= MOD

        return sum(dp[m]) % MOD

    # Binary search to find the minimum length m such that there are at least k valid sequences
    low, high = 1, 1000
    while low < high:
        mid = (low + high) // 2
        if count_sequences(mid) >= k:
            high = mid
        else:
            low = mid + 1

    m = low
    dp = [[0] * n for _ in range(m + 1)]
    dp[0][0] = 1
    prev = [0] * n

    for i in range(1, m + 1):
        for j in range(n):
            for p in range(1, n):
                if (j + p) % n != 0:
                    dp[i][(j + p) % n] += dp[i - 1][j]
                    dp[i][(j + p) % n] %= MOD

    # Reconstruct the kth sequence
    sequence = []
    current_sum = 0
    for i in range(m - 1, -1, -1):
        for p in range(1, n):
            if (current_sum + p) % n != 0 and dp[i][(current_sum + p) % n] > 0:
                sequence.append(p)
                current_sum = (current_sum + p) % n
                break

    return sequence[::-1]

