        prefix_sum_mod = [0] * (len(seq) + 1)
        for i in range(len(seq)):
            prefix_sum_mod[i + 1] = (prefix_sum_mod[i] + seq[i]) % n
        seen = set()
        for i in range(1, len(seq) + 1):
            if prefix_sum_mod[i] in seen:
                return False
            seen.add((prefix_sum_mod[i] - prefix_sum_mod[i - 1]) % n)
        return True

    def generate_sequences(n, k):
        count = 0
        stack = []
        while True:
            if len(stack) == n - 1:
                count += 1
                if count == k:
                    return stack[:]
            if len(stack) < n - 1:
                for i in range(1, n):
                    stack.append(i)
                    if is_valid_sequence(stack):
                        break
                    stack.pop()
                else:
                    stack.pop()
            else:
                stack.pop()

    return generate_sequences(n, k)

