                return False
            seen.add(prefix_sums[i])
        return True

    def backtrack(seq, k):
        if len(seq) == n - 1:
            return seq if is_valid(seq) else None
        for i in range(1, n):
            result = backtrack(seq + [i], k)
            if result:
                return result
            k -= 1
        return None

    return backtrack([], k)

