def find_kth_sequence(n, k):
    def is_valid_sequence(seq):
        prefix_sum = [0]
        for num in seq:
            prefix_sum.append((prefix_sum[-1] + num) % n)
        seen = set()
        for i in range(1, len(prefix_sum)):
            if prefix_sum[i] in seen:
                return False
            seen.add(prefix_sum[i])
        return True

    def dfs(seq, k):
        if len(seq) == n - 1:
            if is_valid_sequence(seq):
                return seq
            return None
        for i in range(1, n):
            result = dfs(seq + [i], k)
            if result:
                return result
        return None

    return dfs([], k)

